import java.util.stream.Collectors;

public class ClaimOffice {

    private static final int PROCESSING_FEE_IN_G = 5;

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_PRICE_LIST_IN_G = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private final Customer customer;

    private final ComponentPriceList componentPriceList = new ComponentPriceList();

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    public int basePremium(List<Item> items) {
        return mainItemsBasePremium(items) + componentsBasePremium(items);
    }

    private int mainItemsBasePremium(List<Item> items) {
        return items.stream()
                .filter(item -> !isComponent(item))
                .mapToInt(item -> MAIN_ITEM_BASE_PREMIUM_PRICE_LIST_IN_G.get(item.type()))
                .sum();
    }

    private int componentsBasePremium(List<Item> items) {
        Map<String, Long> countsByType = items.stream()
                .filter(this::isComponent)
                .collect(Collectors.groupingBy(Item::type, Collectors.counting()));
        return countsByType.values().stream()
                .mapToInt(count -> componentPriceList.alikeComponentsBasePremium(count.intValue()))
                .sum();
    }

    private boolean isComponent(Item item) {
        return componentPriceList.covers(item.type());
    }

    public int quote(List<Item> items) {
        return PROCESSING_FEE_IN_G;
    }
}
